"""Helpers for Step 1: append rows to RESULT, log lines to LOG."""
import csv, io, os, subprocess, sys
ROOT = "/home/jess/Documents/primary_juvenile_meta-analysis/"
RESULT = ROOT + "data/inference_test/results/opus-5-5.csv"
LOG = ROOT + "data/inference_test/logs/opus-5-5_log.csv"
COLS = ["genus","species","subsp","scientific_name","native_status","family",
 "fire_response_categorical_surv1","fire_response_implied","resprouter_type",
 "pjp_mths","primary_juvenile_period","age_at_first_flower_production_from_seed_repr3",
 "secondary_juvenile_period","time_to_first_flower_production_resprout_repr3a",
 "time_to_50_percent_flowering_repr4","time_to_50_percent_flowering","time_to_80_percent_flowering",
 "recovery_time","time_unit","error_column","error_type","error_value","sample_size",
 "location_name","latitude","longitude","rainfall_mm","rainfall_post_fire_mm","rainfall_post_fire_period",
 "fire_type","fire_season_categorical","fire_severity_categorical",
 "supplementary_material","notes","source","file_name"]
LOGCOLS = "paper,status,n_rows,started,finished,note,n_requests,input_tokens,cache_creation_input_tokens,cache_read_input_tokens,output_tokens,total_tokens".split(",")

def _w(path, rows):
    buf = io.StringIO()
    w = csv.writer(buf, lineterminator="\n")
    for r in rows: w.writerow(r)
    with open(path, "a", encoding="utf-8", newline="") as f: f.write(buf.getvalue())

def init():
    if not os.path.exists(RESULT): _w(RESULT, [COLS])
    if not os.path.exists(LOG): _w(LOG, [LOGCOLS])

def clean(v):
    v = "" if v is None else str(v)
    return v.replace("–", "-").replace("—", "-").replace("‐", "-").replace("‑", "-").strip()

def add(rows):
    """rows: list of dicts; unknown keys raise."""
    out = []
    for r in rows:
        bad = set(r) - set(COLS)
        if bad: raise KeyError(bad)
        out.append([clean(r.get(c, "")) for c in COLS])
    _w(RESULT, out)
    return len(out)

def na_row(stem, reason, source=None, supp="NA"):
    r = {c: "NA" for c in COLS}
    r.update(notes=reason, source=source or stem, file_name=stem, supplementary_material=supp)
    return add([r])

def now():
    return subprocess.check_output(["date", "-u", "+%FT%TZ"], text=True).strip()

def log(paper, status, n, started, finished, note):
    _w(LOG, [[paper, status, n, started, finished, clean(note)] + [""] * 6])

def remove_rows(stem):
    with open(RESULT, encoding="utf-8", newline="") as f: rows = list(csv.reader(f))
    keep = [rows[0]] + [r for r in rows[1:] if r[-1] != stem]
    n = len(rows) - len(keep)
    if n:
        buf = io.StringIO(); csv.writer(buf, lineterminator="\n").writerows(keep)
        open(RESULT, "w", encoding="utf-8", newline="").write(buf.getvalue())
    return n
